INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind alle A-Kunden automatisch Großkunden?', 2, '[{"text": "Nein", "correct": true, "because": "Wert, nicht Volumen zählt"}, {"text": "Ja", "correct": false, "because": "Kategorisierung nach Umsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kategorie bringt mir den meisten Umsatz?', 3, '[{"text": "A-Kunden", "correct": true, "because": "80% Umsatz, 20% Kunden"}, {"text": "B-Kunden", "correct": false, "because": "Mittlerer Beitrag"}, {"text": "C-Kunden", "correct": false, "because": "Geringster Umsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale haben C-Kunden?', 5, '[{"text": "Viele in Anzahl", "correct": true, "because": "Ca. 50% der Kunden"}, {"text": "Geringer Umsatz", "correct": true, "because": "Nur 5-10% Beitrag"}, {"text": "Hohe Betreuung", "correct": false, "because": "Wenig Aufwand"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) A-Kunden sind selten. b) C-Kunden sind unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "C-Kunden haben Wert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Kundenklassifizierung?', 4, '[{"text": "Umsatzbeitrag", "correct": false, "because": "Kern der Analyse"}, {"text": "Kundenanzahl", "correct": false, "because": "Definiert Verteilung"}, {"text": "Firmenfarben", "correct": true, "because": "Irrelevant für Wert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob B-Kunden mehr als 50% des Umsatzes ausmachen?', 2, '[{"text": "Nein", "correct": true, "because": "Typisch 15-20%"}, {"text": "Ja", "correct": false, "because": "A-Kunden dominieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gruppe braucht die meiste Aufmerksamkeit?', 3, '[{"text": "A-Kunden", "correct": true, "because": "Höchster Umsatzanteil"}, {"text": "B-Kunden", "correct": false, "because": "Mittlere Priorität"}, {"text": "C-Kunden", "correct": false, "because": "Geringer Beitrag"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Analyse von ABC-Kunden?', 5, '[{"text": "Umsatzsortierung", "correct": true, "because": "Basis der Einteilung"}, {"text": "Kategorisierung", "correct": true, "because": "A, B, C festlegen"}, {"text": "Produktanzahl", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) A-Kunden sind 20% der Kunden. b) C-Kunden sind profitabel. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "C-Kunden oft wenig profitabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist kontextabhängig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Einteilung unwichtig?', 4, '[{"text": "Umsatzdaten", "correct": false, "because": "Grundlage der Analyse"}, {"text": "Prozentuale Verteilung", "correct": false, "because": "Definiert Kategorien"}, {"text": "Kundenalter", "correct": true, "because": "Nicht umsatzrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind A-Kunden immer loyal?', 2, '[{"text": "Nein", "correct": true, "because": "Loyalität nicht garantiert"}, {"text": "Ja", "correct": false, "because": "Umsatzbasierte Einteilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt die Fokussierung auf A-Kunden?', 4, '[{"text": "Hoher Umsatz", "correct": true, "because": "Maximierung der Einnahmen"}, {"text": "Effiziente Ressourcennutzung", "correct": true, "because": "Wenig Kunden, viel Ertrag"}, {"text": "Geringer Aufwand", "correct": false, "because": "Braucht oft mehr Betreuung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass C-Kunden vernachlässigt werden sollten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können Potenzial haben"}, {"text": "Ja", "correct": false, "because": "Nicht komplett ignorieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Kundenanalyse?', 3, '[{"text": "Umsatzanteil", "correct": true, "because": "Definiert Priorität"}, {"text": "Kundenzufriedenheit", "correct": false, "because": "Sekundär"}, {"text": "Anzahl Bestellungen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) B-Kunden sind Übergangskunden. b) A-Kunden sind immer rentabel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rentabilität nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile haben C-Kunden?', 5, '[{"text": "Geringer Umsatz", "correct": true, "because": "Wenig Beitrag"}, {"text": "Hohe Anzahl", "correct": true, "because": "Viel Verwaltungsaufwand"}, {"text": "Hohe Loyalität", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Analyse unwichtig?', 3, '[{"text": "Kategoriengrenze", "correct": false, "because": "Definiert A, B, C"}, {"text": "Umsatzdaten", "correct": false, "because": "Kern der Methode"}, {"text": "Kundengröße", "correct": true, "because": "Nicht umsatzrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein C-Kunde zu A werden?', 3, '[{"text": "Ja", "correct": true, "because": "Umsatz kann steigen"}, {"text": "Nein", "correct": false, "because": "Dynamische Einteilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Analyse auch für Dienstleistungen gilt?', 2, '[{"text": "Ja", "correct": true, "because": "Umsatzbasierte Methode"}, {"text": "Nein", "correct": false, "because": "Nicht produktbeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kategorie wähle ich für intensive Betreuung?', 4, '[{"text": "A-Kunden", "correct": true, "because": "Höchster Umsatzanteil"}, {"text": "B-Kunden", "correct": false, "because": "Mittlere Priorität"}, {"text": "C-Kunden", "correct": false, "because": "Geringer Ertrag"}]');
